/* Presentation-only navigation; it never changes inputs or RK4 routing. */
(() => {
  const work=document.querySelector('.module-workspace'); if(!work)return;
  const zh=()=>document.documentElement.lang==='zh-Hant', pages=new Map(),host=document.createElement('div'),tabs=document.createElement('nav');
  host.id='workspacePageHost';tabs.id='workspacePageTabs';tabs.setAttribute('aria-label','PondGate pages');
  ['route','screen','evidence','learn'].forEach(id=>{const page=document.createElement('section');page.className='workspace-page';page.dataset.page=id;pages.set(id,page);host.appendChild(page);});work.insertBefore(host,work.firstChild);
  const move=(id,page)=>{const el=document.getElementById(id);if(el)pages.get(page).appendChild(el);};
  ['userGuide','mod-inflow','mod-storage','mod-outlet','mod-routing'].forEach(id=>move(id,'route'));const contract=work.querySelector('.principle-contract');if(contract)pages.get('route').insertBefore(contract,pages.get('route').firstChild);
  move('mod-optimization','screen');move('mod-evaluation','evidence');move('teachingAssistant','learn');move('qualityAssurance','learn');let active='route',routeFocus=null;
  const labels=()=>zh()?[['route','設定與路由','模組 1–4'],['screen','受限設計篩選','模組 5'],['evidence','結果、驗證與紀錄','模組 6'],['learn','教學與內部測試','自學／QA']]:[['route','Setup and routing','Modules 1–4'],['screen','Constrained screening','Module 5'],['evidence','Results, verification and records','Module 6'],['learn','Teaching and internal tests','Learning / QA']];
  const children=()=>zh()?[['mod-inflow','1. 入流邊界'],['mod-storage','2. 蓄水量—水位狀態'],['mod-outlet','3. 出口水理'],['mod-routing','4. 第一性原理路由演算']]:[['mod-inflow','1. Inflow boundary'],['mod-storage','2. Storage–water-level state'],['mod-outlet','3. Outlet hydraulics'],['mod-routing','4. First-principles routing']];
  function mount(){const nav=document.getElementById('moduleNavContent');if(!nav)return false;nav.querySelectorAll('.module-link').forEach(x=>{x.hidden=true;x.style.display='none';});if(!nav.contains(tabs))nav.prepend(tabs);return true;}
  function draw(){if(!mount())return;tabs.innerHTML=labels().map(([id,title,sub])=>`<div class="workspace-group"><button type="button" class="workspace-tab${id===active?' active':''}" data-workspace-page="${id}" aria-selected="${id===active}"><span>${title}</span><small>${sub}</small></button>${id==='route'&&active==='route'?`<div class="workspace-children">${children().map(([target,label])=>`<button type="button" class="workspace-child${target===routeFocus?' active':''}" data-workspace-target="${target}">${label}</button>`).join('')}</div>`:''}</div>`).join('');tabs.dataset.activePage=active;tabs.dataset.activeTarget=routeFocus||'';pages.forEach((page,id)=>page.hidden=id!==active);['mod-inflow','mod-storage','mod-outlet','mod-routing'].forEach(id=>{const el=document.getElementById(id);if(el)el.hidden=!(active==='route'&&(!routeFocus||routeFocus===id));});const guide=document.getElementById('userGuide');if(guide)guide.hidden=active==='route'&&Boolean(routeFocus);if(contract)contract.hidden=active==='route'&&Boolean(routeFocus);}
  function activate(id,focus=null){if(!pages.has(id))return;active=id;routeFocus=id==='route'?focus:null;draw();document.dispatchEvent(new CustomEvent('dss:workspace-change',{detail:{page:active,target:routeFocus}}));}
  function openTarget(id){const page={'mod-inflow':'route','mod-storage':'route','mod-outlet':'route','mod-routing':'route','mod-optimization':'screen','mod-evaluation':'evidence','teachingAssistant':'learn','qualityAssurance':'learn'}[id];if(page)activate(page,page==='route'?id:null);}
  tabs.addEventListener('click',e=>{const p=e.target.closest('[data-workspace-page]'),t=e.target.closest('[data-workspace-target]');if(p)activate(p.dataset.workspacePage);if(t)openTarget(t.dataset.workspaceTarget);});document.addEventListener('click',e=>{const link=e.target.closest?.('.module-link[data-target]');if(link){e.preventDefault();e.stopImmediatePropagation();openTarget(link.dataset.target);}if(e.target.closest?.('#teachingNavButton')){e.preventDefault();openTarget('teachingAssistant');}},true);document.getElementById('run')?.addEventListener('click',()=>window.setTimeout(()=>activate('evidence'),120));document.getElementById('lang')?.addEventListener('click',()=>window.setTimeout(draw,0));
  const style=document.createElement('style');style.textContent=`#workspacePageTabs{display:grid;gap:10px;margin:0 0 12px}.workspace-group{display:grid;gap:5px}.workspace-tab{border:1px solid #b9d4df;border-radius:5px;background:#fff;color:#123247;text-align:left;padding:8px 9px;cursor:pointer;font:inherit}.workspace-tab span{display:block;font-weight:700;font-size:14px}.workspace-tab small{display:block;color:#526a78;font-size:11px;margin-top:1px}.workspace-tab.active{background:#0b557d;color:#fff;border-color:#0b557d}.workspace-tab.active small{color:#dbeef5}.workspace-children{display:grid;gap:5px;margin:0 0 2px;padding:8px;border:1px solid #d6e3e8;border-radius:6px;background:#f8fbfc}.workspace-child{border:1px solid #c7d7df;background:#fff;color:#102a43;text-align:left;padding:8px;border-radius:5px;font:inherit;cursor:pointer}.workspace-child.active{border-color:#0b557d;background:#eaf4f8;font-weight:700}.workspace-page[hidden],.module-card[hidden],#userGuide[hidden],.principle-contract[hidden]{display:none!important}@media(max-width:850px){#workspacePageTabs{grid-column:1/-1;grid-template-columns:1fr 1fr}.workspace-tab{min-height:54px}}`;document.head.appendChild(style);draw();window.DSSWorkspacePages=Object.freeze({activate,openTarget,active:()=>active,target:()=>routeFocus});
})();
